manifest=dict(phase=18,date='2026-11-08',purpose='Sui engineers retain evidence-linked human-reviewed resolutions and reuse them for compatible failures.',direction='Working Precedent',scope='Asset strategy acceptance; production integration and final captures remain.',assets=assets,case=json.loads((root/'design/phase16/case-data.json').read_text()),performance=dict(status='Planning budgets, not measured app performance',logo_svg_bytes=10000,social_png_bytes=150000,optional_hero_webp_bytes=250000,below_fold_capture_bytes=180000,fonts_total_transfer_bytes=250000,rendering='Prefer DOM over screenshot. Reserve media dimensions; lazy-load below-fold captures; no auto-playing video or decorative data requests.'))
